insert into public.digital_workbooks(id,slug,title,program_id,cover_image,source_library_id,is_active) values ('c8cb6b05-838e-4ef9-b7f5-2f55c864f109','hvac-epa608-guided-practice','HVAC and EPA 608 Illustrated Practice Workbook','4226f7f6-fbc1-44b5-83e8-b12ea149e4c7','/images/workbooks/hvac-guided-cover.svg','https://github.com/elevate-for-humanity/Elevate-lms/blob/main/scripts/ops/seed-hvac-guided-workbook.sql',true) on conflict(slug) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,1,'Orientation, Training Expectations and Careers','HVAC guided practice',0,'["Describe how online theory, workbook responses, observed practical skills, and the external EPA exam provide different evidence. Build your personal completion checklist.","Draw your learning sequence and mark which activities require an instructor. Explain why course completion is not EPA certification.","Write three questions for your instructor about equipment access, the exam version, and your hands-on schedule."]'::jsonb,'f1d32b7f-7cd4-44c4-9858-6b756ef21b89'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,2,'System Operation, Tools, Components and Shop Safety','HVAC guided practice',0,'["Draw a cooling system and label compressor, condenser, metering device, and evaporator. Add arrows showing refrigerant flow.","Create a tool-identification table: multimeter, thermometer, scale, vacuum gauge, recovery machine. Describe the measurement or task each supports.","For a damaged lead, unknown refrigerant, and missing eye protection, explain why you stop and whom you contact before supervised work."]'::jsonb,'a80053bb-03c2-4533-a3b8-60c3b92ceaeb'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,3,'Electrical Fundamentals, Wiring and Diagnostic Instruments','HVAC guided practice',0,'["Sketch a simple 24-volt source, switch, and load circuit. Predict current flow when the switch is open and closed.","Calculate current for a hypothetical 24 V circuit with 12 ohms of resistance. Show I = V/R and explain why this is an idealized exercise.","Compare measuring voltage in parallel with measuring resistance on isolated equipment. Describe the instructor-approved safe setup; do not work on live equipment for this exercise."]'::jsonb,'5d54f2f0-08f3-4fd8-bdce-a222c76fa44a'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,4,'Furnaces, Electric Heat, Heat Pumps and Combustion','HVAC guided practice',0,'["Compare electric resistance heating, a gas furnace, and a heat pump: energy input, heat source, and major components.","Draw a heat-pump heating-mode diagram. Explain how indoor and outdoor coil roles differ from cooling mode.","List combustion, electrical, and refrigerant hazards that require qualified supervision. Draft a stop-work response to a suspected carbon-monoxide hazard."]'::jsonb,'ec20b538-40f3-4779-bb2c-bc4777f5e406'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,5,'Refrigeration Cycle, Pressure, Superheat and Subcooling','HVAC guided practice',0,'["Use the animated cycle. Record refrigerant state, relative pressure, and heat direction at all four components. Explain why compressor discharge is vapor.","At the virtual bench, calculate superheat from 50°F suction-line temperature and 40°F evaporating saturation temperature, and subcooling from 105°F condensing saturation and 95°F liquid-line temperature.","Change one virtual reading at a time. Explain the result, the assumed phase, and why readings alone do not justify adding refrigerant."]'::jsonb,'9fc1e9bc-707e-4b3f-95a1-d3f727d1fce1'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,6,'Environmental Protection, Section 608 and Refrigerant Safety','HVAC guided practice',0,'["Build a Core vocabulary sheet distinguishing CFC, HCFC, HFC, ozone-depletion potential, and global-warming potential. Use official EPA references and identify one example refrigerant in each family.","Explain the Montreal Protocol and Clean Air Act in your own words. Distinguish production phaseout from a blanket ban on servicing existing equipment.","Classify a factory-manufactured, charged, hermetically sealed four-pound appliance and a field-assembled four-pound system. Explain why charge weight alone is insufficient."]'::jsonb,'e82b52ba-45a0-4ed4-ac58-335284ddb695'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,7,'Recovery Principles, Sales Rules and Core Practice','HVAC guided practice',0,'["Draw three labeled boxes for recover, recycle, and reclaim. Explain what each establishes and what it does not establish.","Prepare a cylinder-safety and transport research checklist covering identification, approved reusable containers, fill limits, and shipping labels. Cite the current source used; do not improvise a fill procedure.","Compare system-dependent and self-contained recovery. Identify which appliance and recovery-equipment facts must be known before selecting a method."]'::jsonb,'8ac047d1-e197-42da-859b-d62183a1fed0'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,8,'Small Appliances: Recovery Equipment, Procedures and Practice','HVAC guided practice',0,'["Draw the Type I decision tree using recovery-equipment date and appliance-compressor condition. Include the applicable percentage and vacuum alternatives from EPA guidance.","For a ten-ounce example charge, calculate ninety percent and eighty percent. Explain why arithmetic alone does not verify the required recovery procedure.","Sketch high-side and low-side access points on a hypothetical small appliance. Ask your trainer to demonstrate the actual approved recovery setup and record questions; do not perform unsupervised service."]'::jsonb,'5aeceec0-92a6-49d6-9218-cce0ab5c99e6'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,9,'High-Pressure Appliances: Recovery, Leaks, Evacuation and Practice','HVAC guided practice',0,'["Build a Type II evacuation-table worksheet from the current EPA service-practice table. Include appliance category, charge range, equipment date, required level, units, and pressure reference.","Compare leak detection, refrigerant recovery, and dehydration evacuation. Draw the distinct purpose of each stage.","Create two rule-identification scenarios distinguishing Section 608 ozone-depleting-refrigerant requirements from applicable AIM Act HFC requirements. Record source dates and avoid assuming every appliance has identical thresholds."]'::jsonb,'71f4a5cb-677e-49b2-bec1-a690ab9f20c6'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,10,'Low-Pressure Appliances: Recovery, Purging, Safety and Practice','HVAC guided practice',0,'["Draw how a below-atmospheric-pressure chiller can admit air and moisture. Explain what excessive purging may suggest and what it cannot prove alone.","Explain the difference between 25 mm Hg absolute, inches Hg vacuum, and psig. Identify which reference belongs to the applicable low-pressure recovery requirement.","Research the reasons for controlling water-freezing risk during recovery and recharging. Prepare a trainer-question sheet covering vapor versus liquid introduction, equipment limits, and required supervision."]'::jsonb,'42564382-7bf8-424e-8560-68b5b0a7897a'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,11,'Core and Types I, II and III: Comparison and Final Practice','HVAC guided practice',0,'["Create a four-column Core, Type I, Type II, and Type III study map. Assign environmental, legal, recovery, safety, and appliance-specific topics to their appropriate columns.","Write a correction log for five practice errors: the original reasoning, corrected reasoning, supporting source, and a new example.","Complete an exam-readiness checklist covering all four sections, pressure-temperature charts, measurement units, allowed exam materials, and the exam version scheduled by the testing provider."]'::jsonb,'72104275-969b-4973-b237-8808adbae2a8'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,12,'Charging, Gauges, Leak Detection and Recovery Practice','HVAC guided practice',0,'["Use the virtual bench to create three hypothetical sets of saturation and line temperatures. Show superheat and subcooling calculations and units.","Draw a diagnostic sequence that checks airflow, measurement location, refrigerant identification, and manufacturer specifications before drawing a charge conclusion.","Compare an electronic leak detector, a recovery machine, and a vacuum pump. Explain why each has a different purpose and what evidence it can establish."]'::jsonb,'8be12981-5829-487b-8769-90a8a479d1b0'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,13,'Ductwork, Sizing, Brazing, Line Sets and System Startup','HVAC guided practice',0,'["Sketch supply and return airflow paths and mark likely restrictions. Explain why an airflow problem can resemble a refrigerant problem.","Draw a line-set installation planning sheet: equipment identification, approved tubing, routing, support, joining, testing, and startup documentation. Mark every task requiring supervision.","Prepare a startup evidence checklist recording actual measurements and manufacturer targets separately. Explain why a generic workbook value cannot substitute for the equipment specifications."]'::jsonb,'f0e124f0-b7b7-4caf-aed0-5d99ae00c40b'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,14,'Troubleshooting, Failure Scenarios and Customer Communication','HVAC guided practice',0,'["Develop a diagnostic decision tree for a hypothetical system that does not cool. Separate observations from possible causes.","Write a service note using confirmed measurements, unresolved questions, and the next safe diagnostic step. Avoid unsupported promises.","Role-play a customer conversation: explain a restriction, request authorization for further diagnosis, and summarize what has and has not been verified."]'::jsonb,'a605aae6-9e8f-48aa-bd47-d686059f2a9f'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,15,'Construction Safety and External OSHA Training','HVAC guided practice',0,'["Illustrate a training-area hazard map with electrical, trip, lifting, chemical, and ignition hazards. Describe prevention controls.","Distinguish this workbook safety study from completion of an authorized OSHA Outreach course and receipt of its card.","Prepare an instructor-reviewed job hazard analysis for an assigned supervised task. Identify required training, protective equipment, emergency procedures, and stop conditions."]'::jsonb,'ce2dcadf-0647-4364-a39d-6cdefafb5b96'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,16,'First Aid, CPR and External Skills Verification','HVAC guided practice',0,'["Create an emergency-response information card identifying how to summon help, the exact site location, and where approved emergency equipment is stored.","Explain why reading or answering a CPR question does not replace an external provider''s required skills assessment.","Discuss a hypothetical unresponsive-person scenario with a qualified instructor and record the training you still need. Use the current approved provider protocol, not an improvised medical procedure."]'::jsonb,'c80f470b-8250-4c0c-b866-7c2035813aed'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
insert into public.digital_workbook_sections(workbook_id,section_number,title,unit,pdf_page,prompts,lesson_id) select id,17,'Customer Service, Job Readiness and Program Completion','HVAC guided practice',0,'["Prepare an accurate resume separating completed training, supervised skills, and earned external credentials from pending items.","Assemble a portfolio index linking your workbook, practice assessments, observed skill checkoffs, and verified credentials. Identify any missing evidence.","Write your next learning goal and a customer-service explanation of one technical topic in plain language. Ask the instructor to review accuracy."]'::jsonb,'a21cd441-9809-4b22-889e-880948e902b6'::uuid from public.digital_workbooks where slug='hvac-epa608-guided-practice' on conflict(workbook_id,section_number) do nothing;
